B.aTb=new A.a("\u0628\u0639\u062b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062e\u0627\u0644\u062f \u0628\u0646 \u0627\u0644\u0648\u0644\u064a\u062f \u0627\u0644\u0649 \u0628\u0646\u064a \u062c\u0630\u064a\u0645\u0629 \u062f\u0627\u0639\u064a\u0627\u064b \u0627\u0644\u0649 \u0627\u0644\u0627\u0633\u0644\u0627\u0645 \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0641\u064a \u0634\u0647\u0631 \u0634\u0648\u0627\u0644 \u0645\u0646 \u0627\u0644\u0633\u0646\u0629 \u0627\u0644\u062b\u0627\u0645\u0646\u0629 \u0644\u0644\u0647\u062c\u0631\u0629 \u0642\u0628\u0644 \u062d\u0646\u064a\u0646 \u0648\u0645\u0639\u0647 \u062c\u0646\u0648\u062f \u0645\u0646 \u0628\u0646\u064a \u0633\u0644\u064a\u0645 \u0648\u0645\u062f\u0644\u062c \u0648\u0627\u0644\u0627\u0646\u0635\u0627\u0631 \u0648\u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0643\u0627\u0646 \u062a\u0639\u062f\u0627\u062f\u0647\u0645 \u062d\u0648\u0627\u0644\u064a \u062b\u0644\u062b\u0645\u0627\u0626\u0629 \u0648\u062e\u0645\u0633\u064a\u0646 \u0631\u062c\u0644\u0627\u064b \u0641\u0644\u0645\u0627 \u0631\u0623\u0649 \u0628\u0646\u0648 \u062c\u0630\u064a\u0645\u0629 \u0627\u0644\u062c\u064a\u0634 \u0628\u0642\u064a\u0627\u062f\u0629 \u062e\u0627\u0644\u062f \u0623\u062e\u0630\u0648\u0627 \u0627\u0644\u0633\u0644\u0627\u062d\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0645 \u062e\u0627\u0644\u062f: \u0636\u0639\u0648\u0627 \u0627\u0644\u0633\u0644\u0627\u062d \u0641\u0625\u0646 \u0627\u0644\u0646\u0627\u0633 \u0642\u062f \u0623\u0633\u0644\u0645\u0648\u0627\u060c \u0641\u0642\u0627\u0645 \u0631\u062c\u0644 \u0645\u0646\u0647\u0645 \u064a\u0633\u0645\u0649: \u062c\u062d\u062f\u0631\u0627\u064b \u0641\u0642\u0627\u0644: \u0648\u064a\u0644\u0643\u0645 \u064a\u0627\u0628\u0646\u064a \u062c\u0630\u064a\u0645\u0629 \u0625\u0646\u0647 \u062e\u0627\u0644\u062f \u0648\u0627\u0644\u0644\u0647 \u0645\u0627\u0628\u0639\u062f \u0648\u0636\u0639 \u0627\u0644\u0633\u0644\u0627\u062d \u0625\u0644\u0627 \u0627\u0644\u0625\u0633\u0627\u0631\u060c \u0648\u0645\u0627\u0628\u0639\u062f \u0627\u0644\u0625\u0633\u0627\u0631 \u0625\u0644\u0627 \u0636\u0631\u0628 \u0627\u0644\u0623\u0639\u0646\u0627\u0642\u060c \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u0623\u0636\u0639 \u0633\u0644\u0627\u062d\u064a \u0623\u0628\u062f\u0627\u064b \u0641\u0644\u0645 \u064a\u0632\u0627\u0644\u0648\u0627 \u0628\u0647 \u062d\u062a\u0649 \u0648\u0636\u0639 \u0633\u0644\u0627\u062d\u0647\u060c \u0641\u0644\u0645\u0627 \u0648\u0636\u0639 \u0627\u0644\u0633\u0644\u0627\u062d \u0623\u0645\u0631 \u0628\u0647\u0645 \u062e\u0627\u0644\u062f \u0641\u0643\u062a\u0641\u0648\u0627\u060c \u0641\u062f\u0639\u0627\u0647\u0645 \u0627\u0644\u0649 \u0627\u0644\u0627\u0633\u0644\u0627\u0645\u060c \u0641\u0644\u0645 \u064a\u062d\u0633\u0646\u0648\u0627 \u0623\u0646 \u064a\u0642\u0648\u0644\u0648\u0627 \u0623\u0633\u0644\u0645\u0646\u0627\u060c \u0641\u062c\u0639\u0644\u0648\u0627 \u064a\u0642\u0648\u0644\u0648\u0646 \u0635\u0628\u0623\u0646\u0627 \u0635\u0628\u0623\u0646\u0627 \u0648\u062e\u0627\u0644\u062f \u064a\u0623\u062e\u0630 \u0641\u064a\u0647\u0645 \u0623\u0633\u0631\u0627\u064b \u0648\u0642\u062a\u0644\u0627\u064b\u060c \u0641\u0623\u0646\u0643\u0631 \u0639\u0644\u064a\u0647 \u0628\u0639\u0636 \u0623\u0635\u062d\u0627\u0628\u0647 \u0630\u0644\u0643\u060c \u062b\u0645 \u062f\u0641\u0639 \u0627\u0644\u0623\u0633\u0631\u0649 \u0627\u0644\u0649 \u0645\u0646 \u0643\u0627\u0646 \u0645\u0639\u0647 \u062d\u062a\u0649 \u0625\u0630\u0627 \u0623\u0635\u0628\u062d \u064a\u0648\u0645\u0627\u064b \u0623\u0645\u0631 \u062e\u0627\u0644\u062f \u0623\u0646 \u064a\u0642\u062a\u0644 \u0643\u0644 \u0648\u0627\u062d\u062f \u0623\u0633\u064a\u0631\u0647\u060c \u0641\u0627\u0645\u062a\u062b\u0644 \u0627\u0644\u0628\u0639\u0636\u060c \u0648\u0627\u0645\u062a\u0646\u0639 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0639\u0645\u0631 \u0648\u0627\u0645\u062a\u0646\u0639 \u0645\u0639\u0647 \u0622\u062e\u0631\u0648\u0646 \u0645\u0646 \u0642\u062a\u0644 \u0623\u0633\u0631\u0627\u0647\u0645\u060c \u0641\u0644\u0645\u0627 \u0642\u062f\u0645\u0648\u0627 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u062e\u0628\u0631\u0648\u0647\u060c \u0641\u063a\u0636\u0628 \u0648\u0631\u0641\u0639 \u064a\u062f\u064a\u0647 \u0627\u0644\u0649 \u0627\u0644\u0633\u0645\u0627\u0621 \u0642\u0627\u0626\u0644\u0627\u064b: \u0627\u0644\u0644\u0647\u0645 \u0625\u0646\u064a \u0623\u0628\u0631\u0623 \u0625\u0644\u064a\u0643 \u0645\u0645\u0627 \u0635\u0646\u0639 \u062e\u0627\u0644\u062f.",null)
B.aLS=new A.a("\u0648\u062f\u0627\u0631 \u0643\u0644\u0627\u0645 \u0628\u064a\u0646 \u062e\u0627\u0644\u062f \u0648\u0639\u0628\u062f\u0627\u0644\u0631\u062d\u0645\u0646 \u0628\u0646 \u0639\u0648\u0641 \u062d\u0648\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0636\u0648\u0639 \u062d\u062a\u0649 \u0643\u0627\u0646 \u0628\u064a\u0646\u0647\u0645 \u0634\u0631\u060c \u0641\u0642\u062f \u062e\u0634\u064a \u0627\u0628\u0646 \u0639\u0648\u0641 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0645\u0627\u0635\u062f\u0631 \u0639\u0646 \u062e\u0627\u0644\u062f \u062b\u0623\u0631\u0627\u064b \u0644\u0639\u0645\u0647 \u0627\u0644\u0641\u0627\u0643\u0647 \u0628\u0646 \u0627\u0644\u0645\u063a\u064a\u0631\u0629 \u0627\u0644\u0630\u064a \u0642\u062a\u0644\u062a\u0647 \u062c\u0630\u064a\u0645\u0629 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629\u060c \u0648\u0644\u0639\u0644 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0648\u0642\u0639 \u0628\u064a\u0646\u0647\u0645 \u0647\u0648 \u0645\u0627 \u0623\u0634\u0627\u0631 \u0625\u0644\u064a\u0647 \u0627\u0644\u062d\u062f\u064a\u062b \u0627\u0644\u0645\u0631\u0648\u064a \u0639\u0646\u062f \u0645\u0633\u0644\u0645 \u0648\u063a\u064a\u0631\u0647: \u0643\u0627\u0646 \u0628\u064a\u0646 \u0627\u0628\u0646 \u0627\u0644\u0648\u0644\u064a\u062f \u0648\u0639\u0628\u062f\u0627\u0644\u0631\u062d\u0645\u0646 \u0628\u0646 \u0639\u0648\u0641 \u0634\u064a\u0621\u060c \u0641\u0633\u0628\u0647 \u062e\u0627\u0644\u062f\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0644\u0627 \u062a\u0633\u0628\u0648\u0627 \u0623\u062d\u062f \u0645\u0646 \u0623\u0635\u062d\u0627\u0628\u064a \u0641\u0625\u0646 \u0623\u062d\u062f\u0643\u0645 \u0644\u0648 \u0623\u0646\u0641\u0642 \u0645\u062b\u0644 \u0623\u062d\u062f \u0630\u0647\u0628\u0627\u064b \u0645\u0627 \u0623\u062f\u0631\u0643 \u0645\u064f\u062f\u0651\u064e \u0623\u062d\u062f\u0647\u0645 \u0648\u0644\u0627 \u0646\u0635\u064a\u0641\u0647\u060c \u0648\u0628\u0639\u062b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u064a\u0627\u064b \u0641\u0648\u062f\u0649 \u0644\u0647\u0645 \u0642\u062a\u0644\u0627\u0647\u0645 \u0648\u0632\u0627\u062f\u0647\u0645 \u0641\u064a\u0647\u0627 \u062a\u0637\u064a\u064a\u0628\u0627\u064b \u0644\u0646\u0641\u0648\u0633\u0647\u0645 \u0648\u0628\u0631\u0627\u0621\u0629 \u0645\u0646 \u062f\u0645\u0627\u0626\u0647\u0645\u060c \u0648\u0628\u0647\u0630\u0627 \u0627\u0644\u062a\u0635\u0631\u0641 \u0627\u0644\u0646\u0628\u0648\u064a \u0627\u0644\u062d\u0643\u064a\u0645 \u0648\u0627\u0633\u0649 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0646\u064a \u062c\u0630\u064a\u0645\u0629\u060c \u0648\u0627\u0632\u0627\u0644 \u0645\u0627\u0641\u064a \u0646\u0641\u0648\u0633\u0647\u0645 \u0645\u0646 \u0623\u0633\u0649\u0651\u064e \u0648\u062d\u0632\u0646\u060c \u0648\u0643\u0627\u0646 \u0642\u062a\u0644 \u062e\u0627\u0644\u062f \u0644\u0628\u0646\u064a \u062c\u0630\u064a\u0645\u0629 \u062a\u0623\u0648\u0644\u0627\u064b \u0645\u0646\u0647 \u0648\u0627\u062c\u062a\u0647\u0627\u062f\u0627\u064b \u062e\u0627\u0637\u0626\u0627\u064b \u0648\u0630\u0644\u0643 \u0628\u062f\u0644\u064a\u0644 \u0623\u0646 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0644\u0645 \u064a\u0639\u0627\u0642\u0628\u0647 \u0639\u0644\u0649 \u0641\u0639\u0644\u0647.",null)
B.aPa=new A.a("\u0647\u062f\u0645 \u0628\u064a\u0648\u062a \u0627\u0644\u0623\u0648\u062b\u0627\u0646: \u0628\u0639\u062f \u0623\u0646 \u0637\u0647\u0631 \u0627\u0644\u0628\u064a\u062a \u0627\u0644\u062d\u0631\u0627\u0645 \u0645\u0646 \u0627\u0644\u0623\u0648\u062b\u0627\u0646 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u0641\u064a\u0647\u060c \u0643\u0627\u0646 \u0644\u0627\u0628\u062f \u0645\u0646 \u0647\u062f\u0645 \u0627\u0644\u0628\u064a\u0648\u062a \u0627\u0644\u062a\u064a \u0623\u0642\u064a\u0645\u062a \u0644\u0644\u0623\u0648\u062b\u0627\u0646 \u0641\u0643\u0627\u0646\u062a \u0645\u0639\u0627\u0644\u0645 \u0644\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0631\u062f\u062d\u0627\u064b \u0637\u0648\u064a\u0644\u0627\u064b \u0645\u0646 \u0627\u0644\u0632\u0645\u0646\u060c \u0641\u0643\u0627\u0646\u062a \u0633\u0631\u0627\u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u062a\u062a\u0631\u0649 \u0644\u062a\u0637\u0647\u064a\u0631 \u0627\u0644\u062c\u0632\u064a\u0631\u0629 \u0645\u0646\u0647\u0627.",null)
