B.aN6=new A.a("\u0648\u0642\u0627\u0644 \u0639\u0646\u0647\u0627 \u0627\u0628\u0646 \u0643\u062b\u064a\u0631: \u0648\u0642\u0635\u062a\u0647\u0627 \u0645\u0634\u0647\u0648\u0631\u0629 \u0645\u0631\u0648\u064a\u0629 \u0645\u0646 \u0637\u0631\u0642 \u064a\u0634\u062f \u0628\u0639\u0636\u0647\u0627 \u0628\u0639\u0636\u0627 \u060c \u0641\u0639\u0646 \u062e\u0627\u0644\u062f \u0628\u0646 \u062e\u0646\u064a\u0633 \u0627\u0644\u062e\u0632\u0627\u0639\u064a \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0635\u0627\u062d\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062d\u064a\u0646 \u062e\u0631\u062c \u0645\u0646 \u0645\u0643\u0629\u060c \u0648\u062e\u0631\u062c \u0645\u0646\u0647\u0627 \u0645\u0647\u0627\u062c\u0631\u0627\u064b \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0647\u0648 \u0648\u0623\u0628\u0648 \u0628\u0643\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0648\u0645\u0648\u0644\u0649 \u0623\u0628\u064a \u0628\u0643\u0631 \u0639\u0627\u0645\u0631 \u0628\u0646 \u0641\u0647\u064a\u0631\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0648\u062f\u0644\u064a\u0644\u0647\u0645\u0627 \u0627\u0644\u0644\u064a\u062b\u064a \u0639\u0628\u062f \u0627\u0644\u0644\u0647 \u0628\u0646 \u0627\u0644\u0623\u0631\u064a\u0642\u0637\u060c \u0645\u0631\u0648\u0627 \u0639\u0644\u0649 \u062e\u064a\u0645\u062a\u064a \u0623\u0645 \u0645\u0639\u0628\u062f \u0627\u0644\u062e\u0632\u0627\u0639\u064a\u0629\u060c \u0648\u0643\u0627\u0646\u062a \u0628\u0631\u0632\u0629 -\u0643\u0647\u0644\u0629 \u0643\u0628\u064a\u0631\u0629 \u0627\u0644\u0633\u0646\u060c \u062c\u0644\u062f\u0629 -\u0642\u0648\u064a\u0629 \u0635\u0644\u0628\u0629 \u0648\u0642\u064a\u0644 \u0639\u0627\u0642\u0644\u0629\u060c \u062a\u062d\u062a\u0628\u064a -\u0623\u064a \u062a\u062c\u0644\u0633 \u0648\u062a\u0636\u0645 \u064a\u062f\u064a\u0647\u0627 \u0625\u062d\u062f\u0627\u0647\u0645\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u062e\u0631\u0649 \u0639\u0644\u0649 \u0631\u0643\u0628\u062a\u064a\u0647\u0627 \u0648\u062a\u0644\u0643 \u062c\u0644\u0633\u0629 \u0627\u0644\u0623\u0639\u0631\u0627\u0628 \u0628\u0641\u0646\u0627\u0621 \u0627\u0644\u0642\u0628\u0629 \u062b\u0645 \u062a\u0633\u0642\u064a \u0648\u062a\u0637\u0639\u0645.",null)
B.aUj=new A.a("\u0641\u0633\u0623\u0644\u0648\u0647\u0645\u0627 \u0644\u062d\u0645\u0627\u064b \u0648\u062a\u0645\u0631\u0627\u064b\u060c \u0644\u064a\u0634\u062a\u0631\u0648\u0647 \u0645\u0646\u0647\u0627\u060c \u0641\u0644\u0645 \u064a\u0635\u064a\u0628\u0648\u0627 \u0639\u0646\u062f\u0647\u0627 \u0634\u064a\u0626\u0627\u064b \u0645\u0646 \u0630\u0644\u0643\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0642\u0648\u0645 \u0645\u064f\u0631\u0652\u0645\u0650\u0644\u064a\u0646 -\u0646\u0641\u0630 \u0632\u0627\u062f\u0647\u0645\u060c \u0645\u0633\u0646\u062a\u064a\u0646 -\u0623\u064a \u062f\u0627\u062e\u0644\u064a\u0646 \u0641\u064a \u0623\u0633\u064e\u0646\u064e\u0629 \u0648\u0647\u064a \u0627\u0644\u062c\u062f\u0628 \u0648\u0627\u0644\u0645\u062c\u0627\u0639\u0629 \u0648\u0627\u0644\u0642\u062d\u0637\u060c \u0641\u0646\u0638\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0625\u0644\u0649 \u0634\u0627\u0629 \u0641\u064a \u0643\u0633\u0631 \u0627\u0644\u062e\u064a\u0645\u0629 -\u0623\u064a \u062c\u0627\u0646\u0628\u0647\u0627\u060c \u0641\u0642\u0627\u0644: \u0645\u0627 \u0647\u0630\u0647 \u0627\u0644\u0634\u0627\u0629 \u064a\u0627 \u0623\u0645 \u0645\u0639\u0628\u062f\u061f \u0642\u0627\u0644\u062a: \u062e\u0644\u0641\u0647\u0627 \u0627\u0644\u062c\u0647\u062f \u0639\u0646 \u0627\u0644\u063a\u0646\u0645\u060c \u0642\u0627\u0644: \u0641\u0647\u0644 \u0628\u0647\u0627 \u0645\u0646 \u0644\u0628\u0646\u061f \u0642\u0627\u0644\u062a: \u0647\u064a \u0623\u062c\u0647\u062f \u0645\u0646 \u0630\u0644\u0643\u060c \u0642\u0627\u0644: \u0623\u062a\u0623\u0630\u0646\u064a\u0646 \u0623\u0646 \u0623\u062d\u0644\u0628\u0647\u0627\u061f \u0642\u0627\u0644\u062a: \u0628\u0644\u0649 \u0628\u0623\u0628\u064a \u0623\u0646\u062a \u0648\u0623\u0645\u064a\u060c \u0646\u0639\u0645\u060c \u0625\u0646 \u0631\u0623\u064a\u062a \u0628\u0647\u0627 \u062d\u0644\u0628\u0627\u064b \u0641\u0627\u062d\u0644\u0628\u0647\u0627.",null)
