B.aFY=new A.a("\u062d\u062a\u0649 \u0643\u0627\u0646 \u0623\u062e\u064a\u0631\u0627\u064b \u0646\u0635\u064a\u0628 \u0627\u0644\u0648\u0627\u062d\u062f \u0645\u0646\u0647\u0645 \u062a\u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0642\u062f \u0623\u062f\u0631\u0643 \u0627\u0644\u062c\u0646\u0648\u062f \u0635\u0639\u0648\u0628\u0629 \u0627\u0644\u0645\u0648\u0642\u0641 \u0641\u062a\u0642\u0628\u0644\u0648\u0627 \u0647\u0630\u0627 \u0627\u0644\u0625\u062c\u0631\u0627\u0621 \u0628\u0635\u062f\u0648\u0631 \u0631\u062d\u0628\u0629 \u062f\u0648\u0646 \u062a\u0630\u0645\u0631 \u0623\u0648 \u0636\u062c\u0631\u060c \u0628\u0644 \u0625\u0646\u0647\u0645 \u0633\u0627\u0647\u0645\u0648\u0627 \u0641\u064a \u062e\u0637\u0629 \u0642\u0627\u0626\u062f\u0647\u0645 \u0627\u0644\u062a\u0642\u0634\u0641\u064a\u0629 \u0641\u0635\u0627\u0631\u0648\u0627 \u064a\u062d\u0627\u0648\u0644\u0648\u0646 \u0627\u0644\u0625\u0628\u0642\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u062a\u0645\u0631\u0629 \u0623\u0643\u0628\u0631 \u0648\u0642\u062a \u0645\u0645\u0643\u0646 \u060c \u064a\u0642\u0648\u0644 \u062c\u0627\u0628\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0623\u062d\u062f \u0623\u0641\u0631\u0627\u062f \u0647\u0630\u0647 \u0627\u0644\u0633\u0631\u064a\u0629: \u0643\u0646\u0627 \u0646\u0645\u0635\u0647\u0627 \u0643\u0645\u0627 \u064a\u0645\u0635 \u0627\u0644\u0635\u0628\u064a \u062b\u0645 \u0646\u0634\u0631\u0628 \u0639\u0644\u064a\u0647\u0627 \u0645\u0646 \u0627\u0644\u0645\u0627\u0621 \u0641\u062a\u0643\u0641\u064a\u0646\u0627 \u064a\u0648\u0645\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0644\u064a\u0644 \u0648\u0642\u062f \u0633\u0623\u0644 \u0648\u0647\u0628 \u0628\u0646 \u0643\u064a\u0633\u0627\u0646 \u062c\u0627\u0628\u0631\u0627\u064b \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0645\u0627\u062a\u063a\u0646\u064a \u0639\u0646\u0643\u0645 \u062a\u0645\u0631\u0629\u061f \u0641\u0642\u0627\u0644: \u0644\u0642\u062f \u0648\u062c\u062f\u0646\u0627 \u0641\u0642\u062f\u0647\u0627 \u062d\u064a\u0646 \u0641\u0646\u064a\u062a.",null)
B.aOP=new A.a("\u0648\u0642\u062f \u0627\u0636\u0637\u0631 \u0630\u0644\u0643 \u0627\u0644\u062c\u064a\u0634 \u0625\u0644\u0649 \u0623\u0643\u0644 \u0648\u0631\u0642 \u0627\u0644\u0634\u062c\u0631 \u0648\u0642\u0627\u0644 \u062c\u0627\u0628\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647: \u0648\u0643\u0646\u0627 \u0646\u0636\u0631\u0628 \u0628\u0639\u0635\u064a\u0646\u0627 \u0627\u0644\u062e\u0628\u0637 \u060c \u062b\u0645 \u0646\u0628\u0644\u0647 \u0628\u0627\u0644\u0645\u0627\u0621 \u0641\u0646\u0623\u0643\u0644\u0647 \u0641\u0633\u0645\u0649 \u0630\u0644\u0643 \u0627\u0644\u062c\u064a\u0634 \u062c\u064a\u0634 \u0627\u0644\u062e\u0628\u0637 -\u0636\u0631\u0628 \u0627\u0644\u0634\u062c\u0631 \u0628\u0627\u0644\u0639\u0635\u0627 \u0644\u064a\u0646\u0627\u062b\u0631 \u0648\u0631\u0642\u0647\u0627- \u0648\u0642\u062f \u0623\u062b\u0631 \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0642\u0641 \u0641\u064a \u0642\u064a\u0633 \u0628\u0646 \u0633\u0639\u062f \u0628\u0646 \u0639\u0628\u0627\u062f\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627 \u0623\u062d\u062f \u062c\u0646\u0648\u062f \u0647\u0630\u0647 \u0627\u0644\u0633\u0631\u064a\u0629 \u0627\u0644\u0634\u062c\u0627\u0639\u0629 \u0648\u0647\u0648 \u0631\u062c\u0644 \u0645\u0646 \u0623\u0647\u0644 \u0628\u064a\u062a \u0627\u0634\u062a\u0647\u0631 \u0628\u0627\u0644\u0643\u0631\u0645\u060c \u0641\u0646\u062d\u0631 \u0644\u0644\u062c\u064a\u0634 \u062b\u0644\u0627\u062b \u062c\u0632\u0627\u0626\u0631 \u062b\u0645 \u0646\u062d\u0631 \u062b\u0644\u0627\u062b \u062c\u0632\u0627\u0626\u0631 \u062b\u0645 \u0646\u062d\u0631 \u062b\u0644\u0627\u062b \u062c\u0632\u0627\u0626\u0631\u060c \u062b\u0645 \u0625\u0646 \u0623\u0628\u0627 \u0639\u0628\u064a\u062f\u0629 \u0646\u0647\u0627\u0647.",null)
