B.aw_=new A.a("\u0642\u0627\u0644 \u0627\u0628\u0646 \u0625\u0633\u062d\u0627\u0642: \u062b\u0645 \u0645\u0636\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0633\u0627\u0626\u0631\u0627\u064b \u0641\u062c\u0639\u0644 \u064a\u062a\u062e\u0644\u0641 \u0639\u0646\u0647 \u0627\u0644\u0631\u062c\u0644\u060c \u0641\u064a\u0642\u0648\u0644\u0648\u0646: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u062a\u062e\u0644\u0641 \u0641\u0644\u0627\u0646 \u0641\u064a\u0642\u0648\u0644: \u062f\u0639\u0648\u0647 \u0641\u0625\u0646 \u064a\u0643 \u0641\u064a\u0647 \u062e\u064a\u0631 \u0641\u0633\u064a\u0644\u062d\u0642\u0647 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0628\u0643\u0645 \u0648\u0625\u0646 \u064a\u0643 \u063a\u064a\u0631 \u0630\u0644\u0643 \u0641\u0642\u062f \u0623\u0631\u0627\u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u060c \u062d\u062a\u0649 \u0642\u064a\u0644: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0642\u062f \u062a\u062e\u0644\u0641 \u0623\u0628\u0648 \u0630\u0631 \u0648\u0623\u0628\u0637\u0623 \u0628\u0647 \u0628\u0639\u064a\u0631\u0647.",null)
B.aGk=new A.a("\u0641\u0642\u0627\u0644: \u062f\u0639\u0648\u0647 \u0641\u0625\u0646 \u064a\u0643 \u0641\u064a\u0647 \u062e\u064a\u0631 \u0641\u0633\u064a\u0644\u062d\u0642\u0647 \u0627\u0644\u0644\u0647 \u0628\u0643\u0645 \u0648\u0625\u0646 \u064a\u0643 \u063a\u064a\u0631 \u0630\u0644\u0643 \u0641\u0642\u062f \u0623\u0631\u0627\u062d\u0643\u0645 \u0627\u0644\u0644\u0647 \u0645\u0646\u0647\u060c \u0648\u062a\u0644\u0648\u0651\u0645 \u0623\u0628\u0648 \u0630\u0631 \u0639\u0644\u0649 \u0628\u0639\u064a\u0631\u0647 - \u0623\u0649 \u062a\u0645\u0647\u0644 - \u0641\u0644\u0645\u0627 \u0623\u0628\u0637\u0623 \u0639\u0644\u064a\u0647 \u0623\u062e\u0630 \u0645\u062a\u0627\u0639\u0647 \u0641\u062d\u0645\u0644\u0647 \u0639\u0644\u0649 \u0638\u0647\u0631\u0647\u060c \u062b\u0645 \u062e\u0631\u062c \u064a\u062a\u0628\u0639 \u0623\u062b\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0645\u0627\u0634\u064a\u0627\u064b\u060c \u0648\u0646\u0632\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0641\u064a \u0628\u0639\u0636 \u0645\u0646\u0627\u0632\u0644\u0647 \u0641\u0646\u0638\u0631 \u0646\u0627\u0638\u0631 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646\u060c \u0641\u0642\u0627\u0644: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0625\u0646 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u064a\u0645\u0634\u064a \u0639\u0644\u0649 \u0627\u0644\u0637\u0631\u064a\u0642 \u0648\u062d\u062f\u0647 \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0643\u0646 \u0623\u0628\u0627 \u0630\u0631\u0651\u060c \u0641\u0644\u0645\u0627 \u062a\u0623\u0645\u0651\u064e\u0644\u0647 \u0627\u0644\u0642\u0648\u0645 \u0642\u0627\u0644\u0648\u0627: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0647\u0648 \u0627\u0644\u0644\u0647 \u0623\u0628\u0648 \u0630\u0631\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0631\u062d\u0645 \u0627\u0644\u0644\u0647 \u0623\u0628\u0627 \u0630\u0631 \u064a\u0645\u0634\u064a \u0648\u062d\u062f\u0647 \u0648\u064a\u0645\u0648\u062a \u0648\u062d\u062f\u0647 \u0648\u064a\u0628\u0639\u062b \u0648\u062d\u062f\u0647\u060c \u0648\u0645\u0636\u0649 \u0627\u0644\u0632\u0645\u0627\u0646 \u0648\u062c\u0627\u0621 \u0639\u0635\u0631 \u0639\u062b\u0645\u0627\u0646 \u062b\u0645 \u062d\u062f\u062b\u062a \u0628\u0639\u0636 \u0627\u0644\u0623\u0645\u0648\u0631 \u0648\u0633\u064f\u064a\u0651\u064e\u0631 \u0623\u0628\u0648 \u0630\u0631 \u0625\u0644\u0649 \u0627\u0644\u0631\u0651\u064e\u0628\u062f\u0629 \u0641\u0644\u0645\u0627 \u062d\u0636\u0631\u0647 \u0627\u0644\u0645\u0648\u062a \u0623\u0648\u0635\u0649 \u0627\u0645\u0631\u0623\u062a\u0647 \u0648\u063a\u0644\u0627\u0645\u0647: \u0625\u0630\u0627 \u0645\u062a\u0651\u064f \u0641\u0627\u063a\u0633\u0644\u0627\u0646\u064a \u0648\u0643\u0641\u0646\u0627\u0646\u064a \u062b\u0645 \u0627\u062d\u0645\u0644\u0627\u0646\u064a \u0641\u0636\u0639\u0627\u0646\u064a \u0639\u0644\u0649 \u0642\u0627\u0631\u0639\u0629 \u0627\u0644\u0637\u0631\u064a\u0642\u060c \u0641\u0623\u0648\u0644 \u0631\u0643\u0628 \u064a\u0645\u0631\u0651\u064f\u0648\u0646 \u0628\u0643\u0645 \u0641\u0642\u0648\u0644\u0648\u0627: \u0647\u0630\u0627 \u0623\u0628\u0648 \u0630\u0631 \u0641\u0644\u0645\u0627 \u0645\u0627\u062a \u0641\u0639\u0644\u0648\u0627 \u0628\u0647 \u0643\u0630\u0644\u0643\u060c \u0641\u0637\u0644\u0639 \u0631\u0643\u0628 \u0641\u0645\u0627 \u0639\u0644\u0645\u0648\u0627 \u0628\u0647 \u062d\u062a\u0649 \u0643\u0627\u062f\u062a \u0631\u0643\u0627\u0626\u0628\u0647\u0645 \u062a\u0637\u0623 \u0633\u0631\u064a\u0631\u0647\u060c \u0641\u0625\u0630\u0627 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u0641\u064a \u0631\u0647\u0637 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u0648\u0641\u0629 \u0641\u0642\u0627\u0644: \u0645\u0627\u0647\u0630\u0627 \u0641\u0642\u064a\u0644: \u062c\u0646\u0627\u0632\u0629 \u0623\u0628\u064a \u0630\u0631 \u0641\u0627\u0633\u062a\u0647\u0644 \u0627\u0628\u0646 \u0645\u0633\u0639\u0648\u062f \u064a\u0628\u0643\u064a \u0641\u0642\u0627\u0644: \u0635\u062f\u0642 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u064a\u0631\u062d\u0645 \u0627\u0644\u0644\u0647 \u0623\u0628\u0627 \u0630\u0631 \u064a\u0645\u0634\u064a \u0648\u062d\u062f\u0647 \u0648\u064a\u0645\u0648\u062a \u0648\u062d\u062f\u0647 \u0648\u064a\u0628\u0639\u062b \u0648\u062d\u062f\u0647\u060c \u0641\u0646\u0632\u0644 \u0641\u0648\u0644\u064a\u0647 \u0628\u0646\u0641\u0633\u0647 \u062d\u062a\u0649 \u062f\u0641\u0646\u0647.",null)
B.aU7=new A.a("\u0644\u0642\u062f \u0628\u0630\u0644 \u0623\u0628\u0648 \u0630\u0631 \u062c\u0647\u062f\u0627\u064b \u0643\u0628\u064a\u0631\u0627\u064b \u0641\u064a \u0627\u0644\u0645\u0634\u064a \u0639\u0644\u0649 \u0642\u062f\u0645\u064a\u0647 \u0648\u0647\u0648 \u064a\u062d\u0645\u0644 \u0645\u062a\u0627\u0639\u0647 \u0639\u0644\u0649 \u0638\u0647\u0631\u0647 \u0648\u062a\u0639\u0631\u0636\u0647 \u0644\u0644\u0635\u0639\u0648\u0628\u0627\u062a \u0648\u0627\u0644\u0645\u062e\u0627\u0637\u0631 \u062d\u062a\u0649 \u064a\u0644\u062d\u0642 \u0628\u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u064a\u0646\u0627\u0644 \u0634\u0631\u0641 \u0627\u0644\u062c\u0647\u0627\u062f \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649.",null)
B.VX=s([B.aw_,B.aGk,B.aU7],t.p)
