B.aUJ=new A.a("\u0638\u0647\u0631\u062a \u062d\u0646\u0643\u062a\u0647 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \ufdfa \u062d\u064a\u0646 \u0627\u062e\u062a\u0627\u0631 \u0642\u0628\u064a\u0644\u0629 \u063a\u0637\u0641\u0627\u0646 \u0628\u0627\u0644\u0630\u0627\u062a \u0644\u0645\u0635\u0627\u0644\u062d\u062a\u0647\u0627 \u0639\u0644\u0649 \u0645\u0627\u0644 \u064a\u062f\u0641\u0639\u0647 \u0625\u0644\u064a\u0647\u0627 \u0639\u0644\u0649 \u0623\u0646 \u062a\u062a\u0631\u0643 \u0645\u062d\u0627\u0631\u0628\u062a\u0647 \u0648\u062a\u0631\u062c\u0639 \u0625\u0644\u0649 \u0628\u0644\u0627\u062f\u0647\u0627\u060c \u0641\u0647\u0648 \u064a\u0639\u0644\u0645 \ufdfa \u0623\u0646 \u063a\u0637\u0641\u0627\u0646 \u0648\u0642\u0627\u062f\u062a\u0647\u0627 \u0644\u064a\u0633 \u0644\u0647\u0645 \u0645\u0646 \u0648\u0631\u0627\u0621 \u0627\u0644\u0625\u0634\u062a\u0631\u0627\u0643 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u063a\u0632\u0648 \u0623\u064a \u0647\u062f\u0641 \u0633\u064a\u0627\u0633\u064a \u064a\u0631\u064a\u062f\u0648\u0646 \u062a\u062d\u0642\u064a\u0642\u0647 \u0623\u0648 \u0628\u0627\u0639\u062b \u0639\u0642\u0627\u0626\u062f\u064a \u064a\u0642\u0627\u062a\u0644\u0648\u0646 \u062a\u062d\u062a \u0631\u0627\u064a\u062a\u0647\u060c \u0648\u0625\u0646\u0645\u0627 \u0643\u0627\u0646 \u0647\u062f\u0641\u0647\u0645 \u0627\u0644\u0623\u0648\u0644 \u0648\u0627\u0644\u0623\u062e\u064a\u0631 \u0645\u0646 \u0627\u0644\u0627\u0634\u062a\u0631\u0627\u0643 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u063a\u0632\u0648 \u0627\u0644\u0643\u0628\u064a\u0631 \u0647\u0648 \u0627\u0644\u062d\u0635\u0648\u0644 \u0639\u0644 \u0627\u0644\u0645\u0627\u0644 \u0628\u0627\u0644\u0625\u0633\u062a\u064a\u0644\u0627\u0621 \u0639\u0644\u064a\u0647 \u0645\u0646 \u062e\u064a\u0631\u0627\u062a \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0639\u0646\u062f \u0627\u062d\u062a\u0644\u0627\u0644\u0647\u0627 \u0648\u0644\u0647\u0630\u0627 \u0644\u0645 \u064a\u062d\u0627\u0648\u0644 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0642\u064a\u0627\u062f\u0629 \u0627\u0644\u0627\u062d\u0632\u0627\u0628 \u0645\u0646 \u0627\u0644\u064a\u0647\u0648\u062f \u0643\u062d\u064a\u064a \u0628\u0646 \u0623\u062e\u0637\u0628\u060c \u0648\u0643\u0646\u0627\u0646\u0629 \u0628\u0646 \u0627\u0644\u0631\u0628\u064a\u0639 \u0623\u0648 \u0642\u0627\u062f\u0629 \u0642\u0631\u064a\u0634 \u0643\u0623\u0628\u064a \u0633\u0641\u064a\u0627\u0646 \u0628\u0646 \u062d\u0631\u0628\u060c \u0644\u0623\u0646 \u0647\u062f\u0641 \u0623\u0648\u0644\u0626\u0643 \u0627\u0644\u0631\u0626\u064a\u0633\u064a\u060c \u0644\u0645 \u064a\u0643\u0646 \u0627\u0644\u0645\u0627\u0644 \u0648\u0625\u0646\u0645\u0627 \u0643\u0627\u0646 \u0647\u062f\u0641\u0647\u0645\u060c \u0647\u062f\u0641\u0627\u064b \u0633\u064a\u0627\u0633\u064a\u0627\u064b \u0648\u0639\u0642\u0627\u0626\u062f\u064a\u0627\u064b \u064a\u062a\u0648\u0642\u0641 \u062a\u062d\u0642\u064a\u0642\u0647 \u0648\u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647 \u0639\u0644\u0649 \u0647\u062f\u0645 \u0627\u0644\u0643\u064a\u0627\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a \u0645\u0646 \u0627\u0644\u0623\u0633\u0627\u0633\u060c \u0644\u0630\u0627 \u0641\u0642\u062f \u0643\u0627\u0646 \u0627\u062a\u0635\u0627\u0644\u0647 \u0641\u0642\u0637 \u0628\u0642\u0627\u062f\u0629 \u063a\u0637\u0641\u0627\u0646\u060c \u0627\u0644\u0630\u064a\u0646 \u0641\u0639\u0644\u0627\u064b \u0644\u0645 \u064a\u062a\u0631\u062f\u062f\u0648\u0627 \u0641\u064a \u0642\u0628\u0648\u0644 \u0627\u0644\u0639\u0631\u0636 \u0627\u0644\u0630\u064a \u0639\u0631\u0636\u0647 \u0639\u0644\u064a\u0647\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u060c \u0641\u0642\u062f \u0627\u0633\u062a\u062c\u0627\u0628 \u0627\u0644\u0642\u0627\u0626\u062f\u0627\u0646 \u0627\u0644\u063a\u0637\u0641\u0627\u0646\u064a\u0627\u0646 \u0639\u064a\u064a\u0646\u0629 \u0628\u0646 \u062d\u0635\u0646\u060c \u0648\u0627\u0644\u062d\u0627\u0631\u062b \u0628\u0646 \u0639\u0648\u0641 \u0644\u0637\u0644\u0628 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u062d\u0636\u0631\u0627 \u0645\u0639 \u0628\u0639\u0636 \u0623\u0639\u0648\u0627\u0646\u0647\u0645\u0627 \u0625\u0644\u0649 \u0645\u0642\u0631 \u0642\u064a\u0627\u062f\u0629 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0627\u062c\u062a\u0645\u0639\u0627 \u0628\u0647 \u0648\u0631\u0627\u0621 \u0627\u0644\u062e\u0646\u062f\u0642 \u0645\u0633\u062a\u062e\u0641\u064a\u0646 \u062f\u0648\u0646 \u0623\u0646 \u064a\u0639\u0644\u0645 \u0628\u0647\u0645\u0627 \u0623\u062d\u062f\u060c \u0648\u0634\u0631\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u0645\u0641\u0627\u0648\u0636\u062a\u0647\u0645 \u0648\u0643\u0627\u0646\u062a \u062a\u062f\u0648\u0631 \u062d\u0648\u0644 \u0639\u0631\u0636 \u062a\u0642\u062f\u0645 \u0628\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u062f\u0639\u0648 \u0641\u064a\u0647 \u0625\u0644\u0649 \u0639\u0642\u062f \u0635\u0644\u062d \u0645\u0646\u0641\u0631\u062f \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646 \u063a\u0637\u0641\u0627\u0646\u060c \u0648\u0645\u0646 \u0628\u0646\u0648\u062f \u0627\u0644\u0627\u062a\u0641\u0627\u0642 : \u062a\u0641\u0643 \u063a\u0637\u0641\u0627\u0646 \u0627\u0644\u062d\u0635\u0627\u0631 \u0639\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0648\u062a\u0646\u0633\u062d\u0628 \u0628\u062c\u064a\u0648\u0634\u0647\u0627 \u0639\u0627\u0626\u062f\u0629 \u0625\u0644\u0649 \u0628\u0644\u0627\u062f\u0647\u0627 \u060c \u0648\u064a\u062f\u0641\u0639 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0644\u063a\u0637\u0641\u0627\u0646 \u0645\u0642\u0627\u0628\u0644 \u0630\u0644\u0643 \u062b\u0644\u062b \u062b\u0645\u0627\u0631 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0643\u0644\u0647\u0627 \u0645\u0646 \u0645\u062e\u062a\u0644\u0641 \u0627\u0644\u0623\u0646\u0648\u0627\u0639\u060c \u0648\u064a\u0638\u0647\u0631 \u0623\u0646 \u0630\u0644\u0643 \u0644\u0633\u0646\u0629 \u0648\u0627\u062d\u062f\u0629.",null)
