B.aDT=new A.a("\u062d\u0627\u0648\u0644 \u0627\u0628\u0646 \u0633\u0644\u0648\u0644 \u0632\u0639\u064a\u0645 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0623\u0646 \u064a\u062d\u0644\u0651 \u062d\u0644\u0641\u0627\u0626\u0647 \u0645\u0646 \u0648\u062b\u0627\u0642\u0647\u0645 \u0641\u0639\u0646\u062f\u0645\u0627 \u0645\u0631\u0651 \u0639\u0644\u064a\u0647\u0645 \u0642\u0627\u0644: \u062d\u0644\u0651\u0648\u0647\u0645 \u0641\u0642\u0627\u0644 \u0627\u0644\u0645\u0646\u0630\u0631: \u0623\u062a\u062d\u0644\u0648\u0646 \u0642\u0648\u0645\u0627\u064b \u0631\u0628\u0637\u0647\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u064a\u062d\u0644\u0647\u0645 \u0631\u062c\u0644 \u0625\u0644\u0627 \u0636\u0631\u0628\u062a \u0639\u0646\u0642\u0647 \u0641\u0627\u0636\u0637\u0631 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u0623\u0628\u064a \u0628\u0646 \u0633\u0644\u0648\u0644 \u0623\u0646 \u064a\u062a\u0631\u0627\u062c\u0639 \u0639\u0646 \u0623\u0645\u0631\u0647 \u0648\u064a\u0644\u062c\u0623 \u0625\u0644\u0649 \u0627\u0633\u062a\u0635\u062f\u0627\u0631 \u0627\u0644\u0623\u0645\u0631 \u0645\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0641\u0643 \u0623\u0633\u0631\u0647\u0645 \u0641\u0623\u062a\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644: \u064a\u0627\u0645\u062d\u0645\u062f \u0623\u062d\u0633\u0646 \u0641\u064a \u0645\u0648\u0627\u0644\u064a -\u0648\u0643\u0627\u0646\u0648\u0627 \u062d\u0644\u0641\u0627\u0621 \u0627\u0644\u062e\u0632\u0631\u062c- \u0642\u0627\u0644: \u0641\u0623\u0628\u0637\u0623 \u0639\u0644\u064a\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644 \u064a\u0627\u0645\u062d\u0645\u062f: \u0623\u062d\u0633\u0646 \u0641\u064a \u0645\u0648\u0627\u0644\u064a \u0642\u0627\u0644: \u0641\u0623\u0639\u0631\u0636 \u0639\u0646\u0647 \u0641\u0623\u062f\u062e\u0644 \u0627\u0628\u0646 \u0623\u0628\u064a \u064a\u062f\u0647 \u0641\u064a \u062c\u064a\u0628\u060c \u0648\u062f\u0631\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0623\u0631\u0633\u0644\u0646\u064a \u0648\u063a\u0636\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u062d\u062a\u0649 \u0631\u0623\u0648\u0627 \u0644\u0648\u062c\u0647\u0647 \u0638\u0644\u0644\u0627\u064b \u062b\u0645 \u0642\u0627\u0644:\u0648\u064a\u062d\u0643 \u0623\u0631\u0633\u0644\u0646\u064a \u0642\u0627\u0644: \u0644\u0627 \u0648\u0627\u0644\u0644\u0647 \u0644\u0627 \u0623\u0631\u0633\u0644\u0643 \u062d\u062a\u0649 \u062a\u062d\u0633\u0646 \u0641\u064a \u0645\u0648\u0627\u0644\u064a \u0623\u0631\u0628\u0639 \u0645\u0627\u0626\u0629 \u062d\u0627\u0633\u0631 \u0648\u062b\u0644\u0627\u062b\u0629 \u0645\u0627\u0626\u0629 \u062f\u0627\u0631\u0639 \u0642\u062f \u0645\u0646\u0639\u0648\u0646\u064a \u0645\u0646 \u0627\u0644\u0623\u062d\u0645\u0631 \u0648\u0627\u0644\u0623\u0633\u0648\u062f \u062a\u062d\u0635\u062f\u0647\u0645 \u0641\u064a \u063a\u062f\u0627\u0629 \u0648\u0627\u062d\u062f\u0629\u060c \u0625\u0646\u064a \u0648\u0627\u0644\u0644\u0647 \u0627\u0645\u0631\u0624 \u0623\u062e\u0634\u0649 \u0627\u0644\u062f\u0648\u0627\u0626\u0631: \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa : \u0647\u0645 \u0644\u0643.",null)
B.aWM=new A.a("\u0641\u062e\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0633\u0628\u064a\u0644\u0647\u0645 \u062b\u0645 \u0623\u0645\u0631 \u0628\u0625\u062c\u0644\u0627\u0626\u0647\u0645 \u0648\u063a\u0646\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0645\u0627\u0643\u0627\u0646 \u0644\u062f\u064a\u0647\u0645 \u0645\u0646 \u0645\u0627\u0644 \u0648\u0642\u062f \u062a\u0648\u0644\u0649 \u062c\u0645\u0639 \u0623\u0645\u0648\u0627\u0644\u0647\u0645 \u0648\u0625\u062d\u0635\u0627\u0621\u0647\u0627 \u0645\u062d\u0645\u062f \u0628\u0646 \u0645\u0633\u0644\u0645\u0629 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0648\u062d\u0627\u0648\u0644 \u0627\u0628\u0646 \u0623\u0628\u064a \u0628\u0646 \u0633\u0644\u0648\u0644 \u0623\u0646 \u064a\u062d\u062f\u062b \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u064a \u064a\u0647\u0648\u062f \u0628\u0646\u064a \u0642\u064a\u0646\u0642\u0627\u0639 \u0644\u0643\u064a \u064a\u064f\u0642\u0631\u0651\u0647\u0645 \u0641\u064a \u062f\u064a\u0627\u0631\u0647\u0645 \u0641\u0648\u062c\u062f \u0639\u0644\u0649 \u0628\u0627\u0628 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u064f\u0648\u064a\u0645 \u0628\u0646 \u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u064a \u0627\u0644\u0623\u0648\u0633\u064a \u0641\u0631\u062f\u0651\u0647 \u0639\u0648\u064a\u0645 \u0648\u0642\u0627\u0644: \u0644\u0627\u062a\u062f\u062e\u0644 \u062d\u062a\u0649 \u064a\u0623\u0630\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0643 \u0641\u062f\u0641\u0639\u0647 \u0627\u0628\u0646 \u0623\u0628\u064a \u0641\u063a\u0644\u0651\u0638 \u0639\u0644\u064a\u0647 \u0639\u0648\u064a\u0645 \u062d\u062a\u0649 \u062c\u062d\u0634 \u0648\u062c\u0647 \u0627\u0628\u0646 \u0623\u0628\u064a \u0627\u0644\u062c\u062f\u0627\u0631 \u0641\u0633\u0627\u0644 \u0627\u0644\u062f\u0645.",null)
